<div class="grid gap-7 lg:grid-cols-[minmax(0,1fr)_360px]"><section class="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200 sm:p-8"><p class="text-sm font-bold uppercase tracking-widest text-blue-600">Student profile</p><h2 class="mt-2 text-2xl font-black text-slate-900">Registration details</h2><p class="mt-2 text-slate-500">All fields marked below are required.</p><?php if(($_GET['msg']??'')==='duplicate'): ?><div class="mt-6 rounded-xl border border-rose-200 bg-rose-50 p-4 text-sm text-rose-700">That student ID is already registered. Try a different ID.</div><?php endif; ?><form action="save-student.php" method="post" enctype="multipart/form-data" class="mt-7 space-y-5"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token']) ?>"><div class="grid gap-5 sm:grid-cols-2"><label class="block text-sm font-bold text-slate-700">Student ID<input class="mt-2 w-full rounded-xl border border-slate-300 px-4 py-3 outline-none focus:border-blue-600 focus:ring-4 focus:ring-blue-100" name="student_id" placeholder="e.g. 2024-0001" required></label><label class="block text-sm font-bold text-slate-700">Section<select class="mt-2 w-full rounded-xl border border-slate-300 bg-white px-4 py-3 outline-none focus:border-blue-600 focus:ring-4 focus:ring-blue-100" name="student_section" required><option value="">Choose a section</option><option>BSIT-4A</option><option>BSIT-4B</option><option>BSCS-4A</option><option>BSCS-4B</option></select></label></div><label class="block text-sm font-bold text-slate-700">Full name<input class="mt-2 w-full rounded-xl border border-slate-300 px-4 py-3 outline-none focus:border-blue-600 focus:ring-4 focus:ring-blue-100" name="student_name" placeholder="Enter the student’s full name" required></label><div class="rounded-xl border border-slate-200 p-4"><div class="flex items-center justify-between gap-3"><div><p class="text-sm font-bold text-slate-700">Biometric image</p><p class="text-sm text-slate-500">Upload a clear face photo or use the camera.</p></div><button id="toggle-camera" type="button" class="rounded-lg border border-blue-200 px-3 py-2 text-sm font-bold text-blue-700 hover:bg-blue-50">Use camera</button></div><div id="upload-area" class="mt-4"><input class="block w-full text-sm text-slate-600 file:mr-4 file:rounded-lg file:border-0 file:bg-blue-50 file:px-4 file:py-2 file:font-bold file:text-blue-700" type="file" name="student_image" id="student_image" accept="image/*"></div><div id="camera-area" class="mt-4 hidden"><video id="webcam" class="w-full rounded-xl bg-slate-900" autoplay playsinline></video><button id="capture-photo" type="button" class="mt-3 rounded-lg bg-slate-800 px-4 py-2 text-sm font-bold text-white">Capture photo</button><canvas id="photo-canvas" class="hidden" width="640" height="480"></canvas><input type="hidden" name="captured_image" id="captured_image"></div></div><button class="w-full rounded-xl bg-blue-600 px-5 py-3 font-bold text-white shadow-sm hover:bg-blue-700">Register student</button></form></section><aside class="h-fit rounded-2xl bg-slate-900 p-6 text-white"><p class="text-sm font-bold uppercase tracking-widest text-blue-300">Preview</p><img id="main-preview" src="../image/student-preview.png" alt="Student image preview" class="mt-5 aspect-square w-full rounded-xl object-cover"><p class="mt-4 text-sm leading-6 text-slate-300">Use a well-lit, front-facing image for the best recognition result.</p></aside></div>
<?php if($toast): ?><div id="toast" class="fixed bottom-5 right-5 rounded-xl bg-slate-900 px-5 py-4 font-semibold text-white shadow-xl"><?= htmlspecialchars($toast) ?></div><?php endif; ?><script>const input=document.getElementById('student_image'),preview=document.getElementById('main-preview'),toggle=document.getElementById('toggle-camera'),cam=document.getElementById('camera-area'),upload=document.getElementById('upload-area'),video=document.getElementById('webcam'),capture=document.getElementById('capture-photo'),canvas=document.getElementById('photo-canvas'),captured=document.getElementById('captured_image');let stream;input.onchange=()=>{if(input.files[0]){preview.src=URL.createObjectURL(input.files[0]);captured.value=''}};toggle.onclick=async()=>{const open=cam.classList.toggle('hidden');upload.classList.toggle('hidden',open);toggle.textContent=open?'Use upload':'Use camera';if(open){try{stream=await navigator.mediaDevices.getUserMedia({video:true});video.srcObject=stream}catch(e){cam.classList.add('hidden');upload.classList.remove('hidden');alert('Camera access was not available.')}}else stream?.getTracks().forEach(t=>t.stop())};capture.onclick=()=>{canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);captured.value=canvas.toDataURL('image/jpeg');preview.src=captured.value};</script><?php adminFoot(); ?>
